  [1271352] = { "Anara Chillwind incanala l'ira di Elune, infondendo in nemici casuali il peso di una singolarità e infliggendo $N1 danni da ombra ogni $D1 per $D2. Quando l'effetto viene rimosso, si forma un buco nero. I nemici all'interno del vuoto subiscono $N4 danni da ombra ogni $D3 e vengono lentamente attirati verso il centro.", "$N1 danni da ombra inflitti ogni $D1. Alla rimozione si forma un Umbral Void. I nemici entro $N3 m subiscono $N4 danni da ombra ogni $D2, la loro velocità di movimento è ridotta del $N6% e vengono lentamente attirati verso il vuoto. Qualsiasi giocatore tocchi il vuoto viene ucciso all'istante.", 0x2fbab7b5, 0xa1e69537, "uu" },
  [1271357] = { "Anara Chillwind incanala la grazia di Elune, infondendo in nemici casuali la potenza di una stella e infliggendo $N1 danni da arcano ogni $D1 per $D2. Quando l'effetto viene rimosso, si forma una stella collassante. I nemici all'interno della stella subiscono $N4 danni da arcano ogni $D3 e hanno la velocità di movimento ridotta del $N6%.", nil, 0xdb5bf191, nil, "um" },
